import unittest

import reports


class ReportsTest(unittest.TestCase):
    def test_export_users_csv(self):
        users = [{"id": "u1", "email": "ada@example.test", "internal": True}]
        self.assertEqual("id,email\r\nu1,ada@example.test\r\n", reports.export_users_csv(users))


if __name__ == "__main__":
    unittest.main()
